    // first shown, where OrcaSlicer closes its own.
    close_splash_when_shown(frame);
    // Before the shell checks below, so the classic presentation gets this
    // too: JusPrin checks for its own new versions, and OrcaSlicer's check,
    // which asks OrcaSlicer's server about OrcaSlicer releases, never runs.
    // Its startup call is left to JusPrin's own schedule; Help > Check for
    // Updates checks at once and, with the shell on, shows Preferences >
    // Updates, where the result appears.
    if (wxGetApp().is_editor()) {
        Updates::update_check().attach(frame);
        // And tells JusPrin's server that this run started, once; see LaunchReport.hpp.
        Updates::report_launch();
        wxGetApp().app_update_check = [](int by_user) {
            if (by_user != 0)
                check_for_updates();
        };
        // Built-in printer and filament profiles change only with a JusPrin
        // release, so OrcaSlicer's profile server is never asked about them,
        // nor Bambu's server for its printer configuration bundle. All three
        // of OrcaSlicer's checks (profiles at startup and on switching to
        // another maker's printer, the bundle at startup) read this preference.
    attach_point() = {&frame, tabpanel, main_sizer};
    if (classic_view_chosen()) {
        install_classic_view();
        return;
    }
    if (install_shell())
        install_classic_view();
}

void check_for_updates()
{
    Updates::update_check().check_now();
    if (ShellController* shell = installed_shell())
        shell->request_preferences("updates");
}

void get_new_version()
{
    Updates::update_check().unskip();
    check_for_updates();
}

void show_open_failure(wxWindow* parent, const Workspace::ProjectAutosave& autosave)
    state.auto_check   = auto_check_enabled(config());
    if (is_running_in_msix())
        state.status = Status::Store;
    else if (m_checking)
        state.status = Status::Checking;
    else if (record.available)
        state.status = Status::Available;
    else if (record.last_failed)
        state.status = Status::Failed;
    else if (record.last_success != 0)
        state.status = Status::UpToDate;
    return state;
}

void UpdateCheck::attach(MainFrame& frame)
{
    // Recreating the GUI builds the new frame before destroying the old one,
    // so the schedule moves to the new frame here and the old frame's
    // destruction leaves it alone.
    m_timer        = std::make_unique<wxTimer>();
    wxTimer* timer = m_timer.get();
    timer->Bind(wxEVT_TIMER, reported("checking for a new version", [this, timer](wxTimerEvent&) {
        const bool at_startup = !m_started;
        m_started             = true;
        if (at_startup)
            timer->Start(kTickMs);
        tick(at_startup);
    }));
    timer->Start(m_started ? kTickMs : kFirstTickMs, m_started ? wxTIMER_CONTINUOUS : wxTIMER_ONE_SHOT);
    frame.Bind(wxEVT_DESTROY, [this, &frame, timer](wxWindowDestroyEvent& event) {
        if (event.GetEventObject() == &frame && m_timer.get() == timer)
            m_timer.reset();
        event.Skip();
    });
}

